Or(a,b){return a+": \xab"+b+"\xbb \u2014 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043e"},
Ot(a,b){return a+": \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u044c \u0443 \u0441\u043f\u0438\u0441\u043a\u0443 \u2014 "+b},
gMu(){return"\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u043e \u0432\u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0456 \u043c\u0435\u0441\u0435\u043d\u0434\u0436\u0435\u0440\u0430"},
gMs(){return"\u0421\u0445\u043e\u0436\u0435, \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e \u0443 \u0432\u0431\u0443\u0434\u043e\u0432\u0430\u043d\u043e\u043c\u0443 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0456. \u0421\u043f\u0438\u0441\u043a\u0438, \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u0456 \u0442\u0443\u0442, \u0437\u0430\u0433\u0443\u0431\u043b\u044f\u0442\u044c\u0441\u044f \u043f\u0456\u0441\u043b\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0443 \u0443 \u0437\u0432\u0438\u0447\u0430\u0439\u043d\u0438\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440. \u041a\u0440\u0430\u0449\u0435: \u043c\u0435\u043d\u044e \u043c\u0435\u0441\u0435\u043d\u0434\u0436\u0435\u0440\u0430 \u2192 \xab\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0456\xbb \u2014 \u0430\u0431\u043e \u0441\u043a\u043e\u043f\u0456\u044e\u0439\u0442\u0435 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0442\u0430 \u0432\u0441\u0442\u0430\u0432\u0442\u0435 \u0439\u043e\u0433\u043e \u0443 \u0431\u0440\u0430\u0443\u0437\u0435\u0440."},
gMt(){return"\u041f\u0440\u043e\u0434\u043e\u0432\u0436\u0438\u0442\u0438 \u0442\u0443\u0442"},
gxM(){return"\u0412\u0445\u0456\u0434 \u0432 \u0430\u043a\u0430\u0443\u043d\u0442"},
